#!/usr/bin/env Rscript
#
# Dumps getR()-interpolated resolution vectors for the isowrap golden
# fixtures (tests/golden/isowrap/), for issue #8's own golden-comparison
# tests (tests/python/test_pipeline.py).
#
# Why this is needed: issue #8's isowrap port takes `resolution` as an
# explicit parameter rather than a calibration table -- getR (`R/getR.R`)
# integration is issue #9's job (branch 9-port-getr-smoothing-spline /
# MR !6), which this branch does not merge or depend on. But the isowrap
# golden fixtures (tools/make_golden.R, issue #3) were generated by R's
# isowrap calling getR *internally* on a resmass calibration table, so
# reproducing the exact resolution values it used requires either
# reimplementing the smoothing-spline interpolation (duplicating #9's
# work, out of scope here) or asking R to compute it once, the same way
# tools/dump_isotopes_precise.R (issue #5) asks R for the isotopes table
# it doesn't have committed yet. This script does the latter: it calls
# the installed R package's own getR() with the exact same pool5/
# checked5/nknots/spar arguments tools/make_golden.R used, and dumps the
# resulting resolution vector so the Python isowrap golden tests can pass
# it in as their `resolution` argument and compare pipeline composition,
# without importing or depending on issue #9's code at all.
#
# Usage: Rscript tools/dump_isowrap_resolution.R <output.csv>

args <- commandArgs(trailingOnly = TRUE)
if (length(args) != 1) {
    stop("usage: Rscript tools/dump_isowrap_resolution.R <output.csv>")
}

suppressMessages(library(enviPat))
data(isotopes); data(chemforms); data(resolution_list)

fmt_num <- function(x) ifelse(is.na(x), NA_character_, sprintf("%.17g", x))

# Reproduce tools/make_golden.R's pool10/pool5 construction exactly.
ck_all <- check_chemform(isotopes, chemforms)
mass_order <- order(ck_all[, 3])
pool10 <- unique(c(
    chemforms[mass_order[1]],
    chemforms[mass_order[length(mass_order)]],
    chemforms[mass_order[round(length(mass_order) / 2)]],
    chemforms[mass_order[round(length(mass_order) / 4)]],
    (chemforms[grepl("Cl[2-9]", chemforms)])[1],
    (chemforms[grepl("Br[1-9]", chemforms)])[1],
    "C1H4",
    "C50H80N10O15S2",
    "[13]C2C8D2H8[15]N2N2[18]O2O3",
    "C20Cl10"
))
pool5 <- pool10[1:5]
checked5 <- check_chemform(isotopes, pool5)

curve_names_3 <- c("Elite_R240000@400", "Q-Exactive,ExactivePlus_R70000@200", "QTOF_XevoG2-S_R25000@200")

rows <- list()
for (curve in curve_names_3) {
    resmass <- resolution_list[[curve]]
    res <- getR(checked5, resmass = resmass, nknots = 6, spar = 0.2, plotit = FALSE)
    for (i in seq_along(res)) {
        rows[[length(rows) + 1]] <- data.frame(
            curve = curve, formula = pool5[i], resolution = fmt_num(res[i]),
            stringsAsFactors = FALSE
        )
    }
}
out <- do.call(rbind, rows)
write.csv(out, args[1], row.names = FALSE)
